/**
 * Dish prices, in PKR, keyed by exact dish name.
 *
 * Every price carries a status so an unverified number can never be mistaken
 * for a signed-off one:
 *
 *   "confirmed"   — signed off by the restaurant. Safe to publish.
 *   "unconfirmed" — sourced from a comparable restaurant's public menu.
 *   "estimated"   — inferred from the price band of similar dishes in the
 *                   same section. A guess, and labelled as one.
 *
 * A dish absent from this map renders N/A, which is the previous site's rule
 * and remains the default for anything we cannot source.
 *
 * ---------------------------------------------------------------------------
 * HOW THESE NUMBERS WERE DERIVED.
 *
 * Source: a comparable Islamabad restaurant's published menu, 36 scans, read
 * page by page. That menu prices its karahi/handi/BBQ "For 2-3 Persons" with
 * Half/Full columns; the Half column is our smaller size. Its printed prices
 * exclude government taxes and a 3% service charge.
 *
 * **Every price here is the reference price exactly.** On 31 August 2026 the
 * owner directed that Flames match the reference menu rather than sit above it,
 * so the 5% markup that had applied since the original derivation was removed
 * from all 124 dishes and all 88 size entries. The basket fell from Rs 264,080
 * to Rs 251,555.
 *
 * Read that history before changing this again. The markup was the owner's own
 * instruction, signed off on 25 Aug 2026, reconfirmed on 26 Aug 2026, and then
 * reversed on 31 Aug 2026. Each entry's `source` names the reference page and
 * the figure taken from it, so any number can still be traced back to a scan.
 *
 * The larger of each sized pair was `unconfirmed` until 31 Aug 2026, when the
 * owner signed the Full / 16-piece prices off as part of the same instruction.
 * Every entry is therefore `confirmed`. Keep the three-state status field: a
 * future price edit that is not owner-approved must not enter as `confirmed`.
 *
 * "Channay" appears in two sections and this map is keyed by name, so the
 * single entry below serves both rows, and both rows share one slug in menu.ts,
 * so they are structurally the same dish. This only becomes work if the owner
 * ever wants the two rows priced differently: that means splitting the dish
 * (new slug), not just this map.
 * ---------------------------------------------------------------------------
 */

export type PriceStatus = "confirmed" | "unconfirmed" | "estimated";

/**
 * One size of a dish that is sold in more than one — "Half" and "Full",
 * "8 pieces" and "16 pieces", "6" and "12".
 */
export interface PriceSize {
  /** How the size reads on the menu. */
  label: string;
  amount: number;
  status: PriceStatus;
  /** Where the number came from, for the sign-off review. */
  source?: string;
}

export interface DishPrice {
  amount: number;
  status: PriceStatus;
  /** Where the number came from, for the sign-off review. */
  source?: string;
  /**
   * Sizes, for a dish sold in more than one. The first entry is the size
   * `amount` names, so a card can fall back to `amount` alone and still be
   * telling the truth.
   *
   * Omitted everywhere at present: the August 2026 derivation took the
   * reference menu's Half column throughout and never priced a full portion,
   * so no second number exists to publish. A size may only be added here once
   * the owner has given it — see the honesty rules in AGENTS.md.
   */
  sizes?: PriceSize[];
}

